export const tacticalScenario=c=>({wave:WAVE_SCENARIOS,ward:WARD_SCENARIOS}[c.type]||[])[c.scenario];
export function tacticalChoices(c){
 const q=tacticalScenario(c);if(!q)return [];
 const choices=c.type==='wave'?Object.keys(WAVE_ACTIONS):q.spots.map(p=>p[0]),offset=(c.variant||0)%choices.length;
 return choices.slice(offset).concat(choices.slice(0,offset));
}
export const tacticalAnswerLabel=(c,answer)=>c.type==='wave'?WAVE_ACTIONS[answer]:tacticalScenario(c)?.spots.find(p=>p[0]===answer)?.[1];
